-- DAT-1020-COO-01 前置二：HR_STAFF_CERTIFICATE 列，CIP_LOG 的第三方与动作取值分布，表单定义表，老系统合同与项目表列名。只看元数据与聚合，不读个人数据。只在 a8_db 上下文出结果。
SELECT N'hr_cols' AS k, c.TABLE_NAME AS a, c.COLUMN_NAME AS b, c.DATA_TYPE AS c FROM a8_db.INFORMATION_SCHEMA.COLUMNS c WHERE DB_NAME() = N'a8_db' AND c.TABLE_NAME IN (N'HR_STAFF_CERTIFICATE', N'HR_STAFF_INFO') ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION;
GO
SELECT N'hr_cert_n' AS k, CAST(COUNT(*) AS nvarchar(20)) AS a, NULL AS b, NULL AS c FROM a8_db.dbo.HR_STAFF_CERTIFICATE WHERE DB_NAME() = N'a8_db';
GO
SELECT TOP 60 N'hr_cert_name' AS k, CAST(CERTIFICATE_NAME AS nvarchar(80)) AS a, CAST(COUNT(*) AS nvarchar(20)) AS b, NULL AS c FROM a8_db.dbo.HR_STAFF_CERTIFICATE WHERE DB_NAME() = N'a8_db' GROUP BY CAST(CERTIFICATE_NAME AS nvarchar(80)) ORDER BY COUNT(*) DESC;
GO
SELECT N'formdef_cols' AS k, c.TABLE_NAME AS a, c.COLUMN_NAME AS b, c.DATA_TYPE AS c FROM a8_db.INFORMATION_SCHEMA.COLUMNS c WHERE DB_NAME() = N'a8_db' AND c.TABLE_NAME = N'CAP_FORM_DEFINITION';
GO
SELECT N'formdef_0642' AS k, CAST(D.ID AS nvarchar(30)) AS a, CAST(D.NAME AS nvarchar(60)) AS b, CAST(LEN(CAST(D.FIELD_INFO AS nvarchar(max))) AS nvarchar(20)) AS c FROM a8_db.dbo.CAP_FORM_DEFINITION D WHERE DB_NAME() = N'a8_db' AND (CAST(D.FIELD_INFO AS nvarchar(max)) LIKE N'%formmain_0642%' OR CAST(D.FIELD_INFO AS nvarchar(max)) LIKE N'%formmain_0307%');
GO
SELECT N'formtables' AS k, t.TABLE_NAME AS a, NULL AS b, NULL AS c FROM a8_db.INFORMATION_SCHEMA.TABLES t WHERE DB_NAME() = N'a8_db' AND (t.TABLE_NAME LIKE N'FORM[_]%' OR t.TABLE_NAME LIKE N'CAP[_]FORM%' OR t.TABLE_NAME LIKE N'CTP[_]FORM%');
GO
SELECT N'cip_third' AS k, CAST(THIRD_PARTY AS nvarchar(60)) AS a, CAST(LOG_ACTION AS nvarchar(80)) AS b, CAST(COUNT(*) AS nvarchar(20)) AS c FROM a8_db.dbo.CIP_LOG WHERE DB_NAME() = N'a8_db' GROUP BY CAST(THIRD_PARTY AS nvarchar(60)), CAST(LOG_ACTION AS nvarchar(80)) ORDER BY COUNT(*) DESC;
GO
SELECT N'econtract_tables' AS k, t.TABLE_NAME AS a, NULL AS b, NULL AS c FROM a8_db.INFORMATION_SCHEMA.TABLES t WHERE DB_NAME() = N'a8_db' AND (t.TABLE_NAME LIKE N'ECONTRACT%' OR t.TABLE_NAME LIKE N'%ESIGN%' OR t.TABLE_NAME LIKE N'%QIANZ%' OR t.TABLE_NAME LIKE N'%SIGN[_]%');
GO
SELECT N'legacy_cols2' AS k, c.TABLE_NAME AS a, c.COLUMN_NAME AS b, c.DATA_TYPE AS c FROM [ruoyi-vue-pro].INFORMATION_SCHEMA.COLUMNS c WHERE DB_NAME() = N'a8_db' AND c.TABLE_NAME IN (N'psa_pm_contract', N'psa_pm_project', N'T_FST_PROJECT') ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION;
GO
SELECT N'legacy_fst_tables' AS k, t.TABLE_NAME AS a, NULL AS b, NULL AS c FROM [ruoyi-vue-pro].INFORMATION_SCHEMA.TABLES t WHERE DB_NAME() = N'a8_db' AND (t.TABLE_NAME LIKE N'T[_]FST%' OR t.TABLE_NAME LIKE N'%curr%' OR t.TABLE_NAME LIKE N'%region%');
GO
